sys_ux_data_broker_transform.script:
function transform(input) {
    var kpiValues = {
        'data': []
    };

    try {
        // Define the property name containing the KPIs
        var propertyName = 'sam.implementation.model.certify';
        var propertyValue = gs.getProperty(propertyName);

        if (propertyValue) {
            var kpis = JSON.parse(propertyValue); // Parse the property JSON
            var order = 0; // Initialize order counter

            kpis.forEach(function (kpi) {
                if (kpi.table && kpi.query) {
                    // Construct URL for the query
                    var instanceBaseURL = gs.getProperty('glide.servlet.uri');
                    var encodedQuery = encodeURIComponent(kpi.query);
                    var queryURL = instanceBaseURL + kpi.table + "_list.do?sysparm_query=" + encodedQuery;

                    // Add the KPI data to the response
                    kpiValues.data.push({
                        "itemId": "checkbox_" + order,
                        "checked": false,
                        "required": false,
                        "order": order,
                        "label": kpi.kpi  ,
						"description":kpi.description,
                        "hasLink": true,
                        "link": {
                            "url": queryURL,
							"title":'View the list of excluded models',
                            "text": "View Records"
                        }
                    });

                    order++; // Increment order for the next KPI
                } else {
                    gs.info("KPI missing table or query: " + JSON.stringify(kpi));
                }
            });
        } else {
            gs.info("Property " + propertyName + " is not set or is empty.");
        }

        // Log the transformed KPI data
        gs.info("Transformed KPI Data: " + JSON.stringify(kpiValues));

    } catch (e) {
        // Handle errors
        gs.error("Error in transform script: " + e.toString());
        return {
            'error': e.toString() // Return error details for debugging
        };
    }

    // Return the transformed data
    return kpiValues;
}
